Item.method_code:
/* globals onRefresh */
if (!options.eventState) {
	options.eventState = window.aras.evalMethod('cui_reinit_calc_tearoff_states');
}

if (options.eventState.isDirty) {
	const dialogSettings = {
		title: aras.getResource('', 'common.refresh')
	};
	const dialogMessage = aras.getResource('', 'common.discard_confirmationmessage');

	return window.ArasModules.Dialog.confirm(dialogMessage, dialogSettings).then(function(result) {
		if (result === 'ok') {
			onRefresh();
		}
	});
}

// タブ表示の更新
if (aras.getMostTopWindowWithAras(window).frames.relationships) {
    var iFramesCollection = aras.getMostTopWindowWithAras(window).frames.relationships.iframesCollection;
    for (var tabId in iFramesCollection) {
        var relshipTypeNd = aras.getRelationshipType(tabId);
        var relshipTypeName = aras.getItemProperty(relshipTypeNd.node, "name");
        if (relshipTypeName === "h4_MQPage Tree Tree") {
            var topWnd = aras.getMostTopWindowWithAras(window);
            var queryString = {
                db: parent.aras.getDatabase(), ITName: thisItem.getType(), relTypeID: tabId, itemID: thisItem.getId(), editMode: (document.isEditMode ? 1 : 0),
                    tabbar: '1', toolbar: '1',
                    where: 'tabview'
            };
                topWnd.relationships.relationshipsControl.reload(queryString);
        }
    }
}// タブ更新ここまで
    
onRefresh();
